-- Initial schema. Target: MySQL 8.0.16+; execute once against an empty database.
SET NAMES utf8mb4;
SET time_zone = '+00:00';
CREATE TABLE branches (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(32) NOT NULL, name VARCHAR(160) NOT NULL, phone VARCHAR(32), email VARCHAR(254), address_line VARCHAR(255), is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_branches_code (code)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE warehouses (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, branch_id BIGINT UNSIGNED NOT NULL, code VARCHAR(32) NOT NULL, name VARCHAR(160) NOT NULL, is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_warehouses_code (code), KEY idx_warehouses_branch (branch_id), CONSTRAINT fk_warehouses_branch FOREIGN KEY (branch_id) REFERENCES branches(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE roles (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(50) NOT NULL, name VARCHAR(100) NOT NULL, description VARCHAR(255), created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_roles_code (code)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE permissions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(100) NOT NULL, description VARCHAR(255), created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_permissions_code (code)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE role_permissions (role_id BIGINT UNSIGNED NOT NULL, permission_id BIGINT UNSIGNED NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (role_id,permission_id), CONSTRAINT fk_role_permissions_role FOREIGN KEY (role_id) REFERENCES roles(id), CONSTRAINT fk_role_permissions_permission FOREIGN KEY (permission_id) REFERENCES permissions(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, branch_id BIGINT UNSIGNED, username VARCHAR(80) NOT NULL, email VARCHAR(254), password_hash VARCHAR(255) NOT NULL, full_name VARCHAR(160) NOT NULL, phone VARCHAR(32), is_active BOOLEAN NOT NULL DEFAULT TRUE, last_login_at DATETIME, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_users_username (username), UNIQUE KEY uq_users_email (email), KEY idx_users_branch (branch_id), CONSTRAINT fk_users_branch FOREIGN KEY (branch_id) REFERENCES branches(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE user_roles (user_id BIGINT UNSIGNED NOT NULL, role_id BIGINT UNSIGNED NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (user_id,role_id), CONSTRAINT fk_user_roles_user FOREIGN KEY (user_id) REFERENCES users(id), CONSTRAINT fk_user_roles_role FOREIGN KEY (role_id) REFERENCES roles(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE customers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(32) NOT NULL, full_name VARCHAR(160) NOT NULL, phone VARCHAR(32) NOT NULL, email VARCHAR(254), address_line VARCHAR(255), notes TEXT, is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_customers_code (code), KEY idx_customers_phone (phone), KEY idx_customers_name (full_name)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE device_types (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(50) NOT NULL, name VARCHAR(120) NOT NULL, is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_device_types_code (code)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE devices (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, customer_id BIGINT UNSIGNED NOT NULL, device_type_id BIGINT UNSIGNED, brand VARCHAR(100), model VARCHAR(120), serial_number VARCHAR(120), description VARCHAR(500), purchase_date DATE, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, KEY idx_devices_customer (customer_id), KEY idx_devices_serial (serial_number), CONSTRAINT fk_devices_customer FOREIGN KEY (customer_id) REFERENCES customers(id), CONSTRAINT fk_devices_type FOREIGN KEY (device_type_id) REFERENCES device_types(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE service_requests (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, branch_id BIGINT UNSIGNED NOT NULL, customer_id BIGINT UNSIGNED NOT NULL, device_id BIGINT UNSIGNED NOT NULL, requested_by_user_id BIGINT UNSIGNED NOT NULL, request_code VARCHAR(32) NOT NULL, issue_description TEXT NOT NULL, requested_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, status VARCHAR(30) NOT NULL DEFAULT 'OPEN', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_service_requests_code (request_code), KEY idx_service_requests_branch_status (branch_id,status), CONSTRAINT chk_service_requests_status CHECK (status IN ('OPEN','CONVERTED','CANCELLED')), CONSTRAINT fk_requests_branch FOREIGN KEY (branch_id) REFERENCES branches(id), CONSTRAINT fk_requests_customer FOREIGN KEY (customer_id) REFERENCES customers(id), CONSTRAINT fk_requests_device FOREIGN KEY (device_id) REFERENCES devices(id), CONSTRAINT fk_requests_creator FOREIGN KEY (requested_by_user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE repair_orders (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, branch_id BIGINT UNSIGNED NOT NULL, customer_id BIGINT UNSIGNED NOT NULL, device_id BIGINT UNSIGNED NOT NULL, service_request_id BIGINT UNSIGNED, original_repair_order_id BIGINT UNSIGNED, received_by_user_id BIGINT UNSIGNED NOT NULL, code VARCHAR(32) NOT NULL, repair_status VARCHAR(30) NOT NULL DEFAULT 'RECEIVED', intake_condition TEXT, reported_issue TEXT NOT NULL, received_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, promised_at DATETIME, completed_at DATETIME, delivered_at DATETIME, labor_total DECIMAL(14,2) NOT NULL DEFAULT 0, parts_total DECIMAL(14,2) NOT NULL DEFAULT 0, discount_total DECIMAL(14,2) NOT NULL DEFAULT 0, tax_total DECIMAL(14,2) NOT NULL DEFAULT 0, notes TEXT, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_repair_orders_code (code), UNIQUE KEY uq_repair_orders_request (service_request_id), KEY idx_repair_orders_branch_status (branch_id,repair_status), KEY idx_repair_orders_customer (customer_id), KEY idx_repair_orders_device (device_id), CONSTRAINT chk_repair_status CHECK (repair_status IN ('RECEIVED','DIAGNOSING','WAITING_APPROVAL','APPROVED','REPAIRING','READY_FOR_PICKUP','DELIVERED','CANCELLED','UNREPAIRABLE')), CONSTRAINT chk_repair_amounts CHECK (labor_total>=0 AND parts_total>=0 AND discount_total>=0 AND tax_total>=0), CONSTRAINT fk_orders_branch FOREIGN KEY (branch_id) REFERENCES branches(id), CONSTRAINT fk_orders_customer FOREIGN KEY (customer_id) REFERENCES customers(id), CONSTRAINT fk_orders_device FOREIGN KEY (device_id) REFERENCES devices(id), CONSTRAINT fk_orders_request FOREIGN KEY (service_request_id) REFERENCES service_requests(id), CONSTRAINT fk_orders_original FOREIGN KEY (original_repair_order_id) REFERENCES repair_orders(id), CONSTRAINT fk_orders_receiver FOREIGN KEY (received_by_user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE repair_assignments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, repair_order_id BIGINT UNSIGNED NOT NULL, technician_user_id BIGINT UNSIGNED NOT NULL, assigned_by_user_id BIGINT UNSIGNED NOT NULL, assigned_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, unassigned_at DATETIME, notes VARCHAR(500), created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY idx_assignment_order_active (repair_order_id,unassigned_at), KEY idx_assignment_technician_active (technician_user_id,unassigned_at), CONSTRAINT fk_assign_order FOREIGN KEY (repair_order_id) REFERENCES repair_orders(id), CONSTRAINT fk_assign_technician FOREIGN KEY (technician_user_id) REFERENCES users(id), CONSTRAINT fk_assign_actor FOREIGN KEY (assigned_by_user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE repair_status_history (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, repair_order_id BIGINT UNSIGNED NOT NULL, from_status VARCHAR(30), to_status VARCHAR(30) NOT NULL, changed_by_user_id BIGINT UNSIGNED NOT NULL, reason VARCHAR(500), changed_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY idx_status_history_order_time (repair_order_id,changed_at), CONSTRAINT chk_history_status CHECK (to_status IN ('RECEIVED','DIAGNOSING','WAITING_APPROVAL','APPROVED','REPAIRING','READY_FOR_PICKUP','DELIVERED','CANCELLED','UNREPAIRABLE')), CONSTRAINT fk_history_order FOREIGN KEY (repair_order_id) REFERENCES repair_orders(id), CONSTRAINT fk_history_actor FOREIGN KEY (changed_by_user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE diagnostics (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, repair_order_id BIGINT UNSIGNED NOT NULL, technician_user_id BIGINT UNSIGNED NOT NULL, diagnosis_text TEXT NOT NULL, recommended_action TEXT, estimated_labor DECIMAL(14,2) NOT NULL DEFAULT 0, diagnosed_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, KEY idx_diagnostics_order_time (repair_order_id,diagnosed_at), CONSTRAINT chk_diagnostic_labor CHECK (estimated_labor>=0), CONSTRAINT fk_diagnostic_order FOREIGN KEY (repair_order_id) REFERENCES repair_orders(id), CONSTRAINT fk_diagnostic_technician FOREIGN KEY (technician_user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE quotes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, repair_order_id BIGINT UNSIGNED NOT NULL, diagnostic_id BIGINT UNSIGNED, version_no INT UNSIGNED NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'DRAFT', labor_amount DECIMAL(14,2) NOT NULL DEFAULT 0, parts_amount DECIMAL(14,2) NOT NULL DEFAULT 0, discount_amount DECIMAL(14,2) NOT NULL DEFAULT 0, tax_amount DECIMAL(14,2) NOT NULL DEFAULT 0, valid_until DATETIME, created_by_user_id BIGINT UNSIGNED NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_quotes_order_version (repair_order_id,version_no), KEY idx_quotes_order_status (repair_order_id,status), CONSTRAINT chk_quote_status CHECK (status IN ('DRAFT','PENDING_CUSTOMER','APPROVED','REJECTED','EXPIRED','SUPERSEDED')), CONSTRAINT chk_quote_amounts CHECK (labor_amount>=0 AND parts_amount>=0 AND discount_amount>=0 AND tax_amount>=0), CONSTRAINT fk_quotes_order FOREIGN KEY (repair_order_id) REFERENCES repair_orders(id), CONSTRAINT fk_quotes_diagnostic FOREIGN KEY (diagnostic_id) REFERENCES diagnostics(id), CONSTRAINT fk_quotes_creator FOREIGN KEY (created_by_user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE quote_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, quote_id BIGINT UNSIGNED NOT NULL, item_type VARCHAR(20) NOT NULL, description VARCHAR(500) NOT NULL, quantity DECIMAL(12,3) NOT NULL DEFAULT 1, unit_price DECIMAL(14,2) NOT NULL, line_total DECIMAL(14,2) NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY idx_quote_items_quote (quote_id), CONSTRAINT chk_quote_item_type CHECK (item_type IN ('LABOR','PART')), CONSTRAINT chk_quote_item_amount CHECK (quantity>0 AND unit_price>=0 AND line_total>=0), CONSTRAINT fk_quote_items_quote FOREIGN KEY (quote_id) REFERENCES quotes(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE quote_decision_history (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, quote_id BIGINT UNSIGNED NOT NULL, decision VARCHAR(20) NOT NULL, decided_by_user_id BIGINT UNSIGNED, decided_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, customer_contact_name VARCHAR(160), note VARCHAR(500), KEY idx_quote_decision_time (quote_id,decided_at), CONSTRAINT chk_quote_decision CHECK (decision IN ('SENT','APPROVED','REJECTED','EXPIRED')), CONSTRAINT fk_quote_decision_quote FOREIGN KEY (quote_id) REFERENCES quotes(id), CONSTRAINT fk_quote_decision_actor FOREIGN KEY (decided_by_user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE inventory_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, sku VARCHAR(64) NOT NULL, name VARCHAR(200) NOT NULL, unit VARCHAR(20) NOT NULL DEFAULT 'piece', standard_cost DECIMAL(14,2) NOT NULL DEFAULT 0, default_sale_price DECIMAL(14,2) NOT NULL DEFAULT 0, reorder_level DECIMAL(12,3) NOT NULL DEFAULT 0, is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_inventory_sku (sku), KEY idx_inventory_name (name), CONSTRAINT chk_inventory_item_amounts CHECK (standard_cost>=0 AND default_sale_price>=0 AND reorder_level>=0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE inventory_stocks (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, warehouse_id BIGINT UNSIGNED NOT NULL, inventory_item_id BIGINT UNSIGNED NOT NULL, quantity_on_hand DECIMAL(12,3) NOT NULL DEFAULT 0, quantity_reserved DECIMAL(12,3) NOT NULL DEFAULT 0, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_stock_warehouse_item (warehouse_id,inventory_item_id), CONSTRAINT chk_stock_amounts CHECK (quantity_on_hand>=0 AND quantity_reserved>=0 AND quantity_reserved<=quantity_on_hand), CONSTRAINT fk_stock_warehouse FOREIGN KEY (warehouse_id) REFERENCES warehouses(id), CONSTRAINT fk_stock_item FOREIGN KEY (inventory_item_id) REFERENCES inventory_items(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE inventory_transactions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, warehouse_id BIGINT UNSIGNED NOT NULL, inventory_item_id BIGINT UNSIGNED NOT NULL, repair_order_id BIGINT UNSIGNED, transaction_type VARCHAR(20) NOT NULL, quantity DECIMAL(12,3) NOT NULL, unit_cost DECIMAL(14,2) NOT NULL DEFAULT 0, occurred_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, performed_by_user_id BIGINT UNSIGNED NOT NULL, note VARCHAR(500), created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY idx_inventory_tx_stock_time (warehouse_id,inventory_item_id,occurred_at), KEY idx_inventory_tx_order (repair_order_id), CONSTRAINT chk_inventory_tx_type CHECK (transaction_type IN ('RECEIPT','ISSUE','ADJUSTMENT_IN','ADJUSTMENT_OUT','RETURN')), CONSTRAINT chk_inventory_tx_amount CHECK (quantity>0 AND unit_cost>=0), CONSTRAINT fk_inventory_tx_warehouse FOREIGN KEY (warehouse_id) REFERENCES warehouses(id), CONSTRAINT fk_inventory_tx_item FOREIGN KEY (inventory_item_id) REFERENCES inventory_items(id), CONSTRAINT fk_inventory_tx_order FOREIGN KEY (repair_order_id) REFERENCES repair_orders(id), CONSTRAINT fk_inventory_tx_actor FOREIGN KEY (performed_by_user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE repair_order_parts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, repair_order_id BIGINT UNSIGNED NOT NULL, inventory_item_id BIGINT UNSIGNED, inventory_transaction_id BIGINT UNSIGNED, description VARCHAR(500) NOT NULL, quantity DECIMAL(12,3) NOT NULL, unit_cost_snapshot DECIMAL(14,2) NOT NULL DEFAULT 0, unit_price_snapshot DECIMAL(14,2) NOT NULL DEFAULT 0, line_total DECIMAL(14,2) NOT NULL DEFAULT 0, created_by_user_id BIGINT UNSIGNED NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY idx_order_parts_order (repair_order_id), CONSTRAINT chk_order_part_amounts CHECK (quantity>0 AND unit_cost_snapshot>=0 AND unit_price_snapshot>=0 AND line_total>=0), CONSTRAINT fk_order_parts_order FOREIGN KEY (repair_order_id) REFERENCES repair_orders(id), CONSTRAINT fk_order_parts_item FOREIGN KEY (inventory_item_id) REFERENCES inventory_items(id), CONSTRAINT fk_order_parts_tx FOREIGN KEY (inventory_transaction_id) REFERENCES inventory_transactions(id), CONSTRAINT fk_order_parts_actor FOREIGN KEY (created_by_user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE repair_labor_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, repair_order_id BIGINT UNSIGNED NOT NULL, description VARCHAR(500) NOT NULL, quantity DECIMAL(12,3) NOT NULL DEFAULT 1, unit_price_snapshot DECIMAL(14,2) NOT NULL, line_total DECIMAL(14,2) NOT NULL, created_by_user_id BIGINT UNSIGNED NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY idx_labor_order (repair_order_id), CONSTRAINT chk_labor_amounts CHECK (quantity>0 AND unit_price_snapshot>=0 AND line_total>=0), CONSTRAINT fk_labor_order FOREIGN KEY (repair_order_id) REFERENCES repair_orders(id), CONSTRAINT fk_labor_actor FOREIGN KEY (created_by_user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE payments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, repair_order_id BIGINT UNSIGNED NOT NULL, received_by_user_id BIGINT UNSIGNED NOT NULL, receipt_number VARCHAR(64) NOT NULL, payment_method VARCHAR(20) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'VALID', amount DECIMAL(14,2) NOT NULL, paid_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, reference_code VARCHAR(120), note VARCHAR(500), voided_at DATETIME, voided_by_user_id BIGINT UNSIGNED, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_payments_receipt (receipt_number), KEY idx_payments_order_status (repair_order_id,status), CONSTRAINT chk_payment_method CHECK (payment_method IN ('CASH','BANK_TRANSFER','CARD','OTHER')), CONSTRAINT chk_payment_status CHECK (status IN ('VALID','VOIDED','REFUNDED')), CONSTRAINT chk_payment_amount CHECK (amount>0), CONSTRAINT fk_payment_order FOREIGN KEY (repair_order_id) REFERENCES repair_orders(id), CONSTRAINT fk_payment_receiver FOREIGN KEY (received_by_user_id) REFERENCES users(id), CONSTRAINT fk_payment_voider FOREIGN KEY (voided_by_user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE warranties (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, repair_order_id BIGINT UNSIGNED NOT NULL, warranty_code VARCHAR(64) NOT NULL, starts_at DATETIME NOT NULL, ends_at DATETIME NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE', terms TEXT, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_warranty_code (warranty_code), KEY idx_warranty_order (repair_order_id), KEY idx_warranty_expiry (status,ends_at), CONSTRAINT chk_warranty_status CHECK (status IN ('ACTIVE','EXPIRED','VOIDED','CLAIMED')), CONSTRAINT chk_warranty_dates CHECK (ends_at>=starts_at), CONSTRAINT fk_warranty_order FOREIGN KEY (repair_order_id) REFERENCES repair_orders(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, actor_user_id BIGINT UNSIGNED, entity_type VARCHAR(80) NOT NULL, entity_id BIGINT UNSIGNED NOT NULL, action VARCHAR(80) NOT NULL, before_data JSON, after_data JSON, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY idx_audit_entity (entity_type,entity_id,created_at), KEY idx_audit_actor_time (actor_user_id,created_at), CONSTRAINT fk_audit_actor FOREIGN KEY (actor_user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
